目前多文件配置对 Object 的处理都是整个覆盖的，这样处理很不灵活，是否可以引入”补充“模式。

### 补充模式建议

默认是之前的模式，整个 Object 覆盖，当字段名添加`:expand`后缀时表示是补充模式（或许可以讨论一下更好的处理方式，总之希望有类似功能），比如下面例子：

- **01_test.jsonc**

```jsonc
{
  "log": {
    "access": "none",
    "error": "/var/log/xray/error.log"
  },
  "api": {
    "tag": "api",
    "listen": "127.0.0.1:8080",
    "services": [
      "HandlerService",
      "LoggerService",
      "StatsService",
      "RoutingService"
    ]
  },
  "inbounds": [
    {
      "tag": "socks",
      "protocol": "socks",
      "listen": "127.0.0.1",
      "settings": {
        "auth": "noauth",
        "users": [
          {
            "user": "my-username",
            "pass": "my-password"
          }
        ],
        "udp": false,
        "ip": "127.0.0.1",
        "userLevel": 0
      },
      "port": 8888,
      "sniffing": {
        "enabled": true,
        "destOverride": ["tls"]
      }
    }
  ]
}
```

- 02_test.jsonc
```jsonc
{
  // 补充模式
  "log:expand": {
    "access": "/var/log/xray/access.log",
    "dnsLog": true,
    "maskAddress": "quarter"
  },
  // 默认模式
  "api": {
    "tag": "api",
    "services": ["HandlerService", "RoutingService"]
  },
  "inbounds": [
    {
      // inbound tag 补充模式
      "tag:expand": "socks",
      "listen": "0.0.0.0",
      // 嵌套补充模式
      "settings:expand": {
        "ip": "0.0.0.0"
      }
    }
  ]
}
